"""YAML to Markdown data pipeline with cleaning: missing values, duplicates, type conversion."""

import argparse
import sys
from pathlib import Path

import yaml


def load_yaml(path: str) -> list[dict]:
    with open(path) as f:
        data = yaml.safe_load(f)
    if isinstance(data, dict):
        # Flatten single-key dict wrapping a list (e.g. {sales: [...]})
        for v in data.values():
            if isinstance(v, list):
                return v
        return [data]
    if isinstance(data, list):
        return data
    raise ValueError(f"Unsupported YAML structure: {type(data)}")


def remove_duplicates(rows: list[dict]) -> list[dict]:
    seen = set()
    unique = []
    for row in rows:
        key = tuple(sorted((str(k), str(v)) for k, v in row.items()))
        if key not in seen:
            seen.add(key)
            unique.append(row)
    return unique


def coerce_type(value):
    """Convert string representations to native Python types."""
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value
    if not isinstance(value, str):
        return value

    lower = value.strip().lower()

    # booleans
    if lower in ("true", "yes", "1"):
        return True
    if lower in ("false", "no", "0"):
        return False

    # numbers
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass

    return value.strip()


def clean_rows(rows: list[dict], fill_value: str = "N/A") -> list[dict]:
    cleaned = []
    for row in rows:
        cleaned_row = {}
        for k, v in row.items():
            v = coerce_type(v)
            if v is None or (isinstance(v, str) and v.strip() == ""):
                v = fill_value
            cleaned_row[k] = v
        cleaned.append(cleaned_row)
    return cleaned


def rows_to_markdown(rows: list[dict]) -> str:
    if not rows:
        return "_No data._\n"

    headers = list(rows[0].keys())
    col_widths = {h: len(h) for h in headers}

    str_rows = []
    for row in rows:
        str_row = {}
        for h in headers:
            val = str(row.get(h, "N/A"))
            str_row[h] = val
            col_widths[h] = max(col_widths[h], len(val))
        str_rows.append(str_row)

    lines = []
    header_line = "| " + " | ".join(h.ljust(col_widths[h]) for h in headers) + " |"
    sep_line = "| " + " | ".join("-" * col_widths[h] for h in headers) + " |"
    lines.append(header_line)
    lines.append(sep_line)

    for row in str_rows:
        line = "| " + " | ".join(row[h].ljust(col_widths[h]) for h in headers) + " |"
        lines.append(line)

    return "\n".join(lines) + "\n"


def run(input_path: str, output_path: str, fill_value: str = "N/A") -> dict:
    rows = load_yaml(input_path)
    original_count = len(rows)

    rows = remove_duplicates(rows)
    dedup_count = original_count - len(rows)

    rows = clean_rows(rows, fill_value=fill_value)

    md = rows_to_markdown(rows)

    Path(output_path).write_text(md)

    return {
        "input_rows": original_count,
        "duplicates_removed": dedup_count,
        "output_rows": len(rows),
        "output_file": output_path,
    }


def main():
    parser = argparse.ArgumentParser(description="YAML → cleaned Markdown table")
    parser.add_argument("input", help="Input YAML file")
    parser.add_argument("-o", "--output", default="cleaned_output.md", help="Output Markdown file")
    parser.add_argument("--fill", default="N/A", help="Fill value for missing/empty fields")
    args = parser.parse_args()

    stats = run(args.input, args.output, fill_value=args.fill)
    print(f"Processed {stats['input_rows']} rows → {stats['output_rows']} rows "
          f"({stats['duplicates_removed']} duplicates removed)")
    print(f"Saved to {stats['output_file']}")


if __name__ == "__main__":
    main()
